// 1. Fetch data from previous nodes
const projectIndexRaw = $items("Fetch Project Index")[0].json.data;
const skeletonTemplateRaw = $items("Fetch Skeleton Template")[0].json.data;
const calendarRaw = $items("Fetch Calendar Feed")[0].json.data;
const feedsRaw = $items("Fetch Feeds File")[0].json.data || '';

// 2. Clean and parse JSON strings (removing markdown wrappers)
const cleanProjectJson = projectIndexRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const projects = JSON.parse(cleanProjectJson);

const cleanCalendarJson = calendarRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const events = JSON.parse(cleanCalendarJson);

// 2b. Build set of project IDs that have real feed signals
// Exclude meta-buckets that don't map to a specific project
const META_BUCKETS = new Set(['PERSONAL', 'PERSONAL_ADMIN', 'MISC', 'NOISE']);
let projectsWithSignals = new Set();
try {
  const cleanFeedsJson = feedsRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const feeds = JSON.parse(cleanFeedsJson);
  for (const signal of feeds) {
    if (signal.project_id && !META_BUCKETS.has(signal.project_id)) {
      projectsWithSignals.add(signal.project_id);
    }
  }
} catch (e) {
  // If feeds file is missing or malformed, fail open — stamp callouts for all projects
  projectsWithSignals = null;
}

// 3. Split into housekeeping vs active projects
const housekeepingProjects = projects.filter(p => p.priority === '\uD83D\uDD35 HOUSEKEEPING');
const activeProjects = projects.filter(p => p.priority !== '\uD83D\uDD35 HOUSEKEEPING');

// 4. Sort active projects by priority: URGENT first, then IMPORTANT, then ON THE RADAR
activeProjects.sort((a, b) => {
  const rank = p => p.priority.includes('URGENT') ? 0 : p.priority.includes('IMPORTANT') ? 1 : 2;
  return rank(a) - rank(b);
});

// 5. Build formatted day string
const now = new Date();
const dayFormatted = now.toLocaleDateString('en-NZ', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'Pacific/Auckland'
});

// 6. Process Calendar Table Rows
const seenEvents = new Set();

const calendarRows = events
  .filter(event => event.title && event.title !== "(No title)" && event.start)
  .filter(event => {
    const nztDate = new Date(event.start).toLocaleDateString('en-NZ', { timeZone: 'Pacific/Auckland', year: 'numeric', month: '2-digit', day: '2-digit' });
    const cleanTitle = event.title.trim().toLowerCase().replace(/[\u2018\u2019]/g, "'");
    const uniqueKey = `${cleanTitle}|${nztDate}`;
    if (seenEvents.has(uniqueKey)) return false;
    seenEvents.add(uniqueKey);
    return true;
  })
  .map(event => {
    const dateObj = new Date(event.start);
    const dayStr = dateObj.toLocaleDateString('en-NZ', { weekday: 'short', day: '2-digit', month: 'short', timeZone: 'Pacific/Auckland' });
    const timeStr = event.all_day ? "All Day" : dateObj.toLocaleTimeString('en-NZ', { hour: '2-digit', minute: '2-digit', timeZone: 'Pacific/Auckland' });
    const emoji = event.calendar === 'work' ? '\uD83D\uDCBC' : event.calendar === 'family' ? '\uD83C\uDFE0' : '\uD83D\uDCC5';
    const sanitizedLocation = event.location ? event.location.replace(/\n/g, ', ') : '';
    const location = sanitizedLocation ? ` @ ${sanitizedLocation}` : '';
    return `| ${dayStr} | ${emoji} ${event.title.trim()} | ${timeStr}${location} |`;
  })
  .join('\n');

// 7. Isolate the repeatable project template block
const activeProjectsSplit = skeletonTemplateRaw.split('## \uD83D\uDCD0 Active Projects');
let topPart = activeProjectsSplit[0] + '## \uD83D\uDCD0 Active Projects\n\n';

const resolvedSplit = activeProjectsSplit[1].split('## \u2705 Resolved Since Last Briefing');
const projectSectionRaw = resolvedSplit[0];

const projectBlockMatch = projectSectionRaw.match(/###[\s\S]*?(?=###|$)/);
let projectTemplate = projectBlockMatch ? projectBlockMatch[0].trim() : projectSectionRaw.replace(/---\s*$/, '').trim();

// Strip any trailing --- from the project template
projectTemplate = projectTemplate.replace(/\n+---\s*$/, '').trim();

const bottomPart = '\n\n---\n\n## \u2705 Resolved Since Last Briefing' + resolvedSplit[1];

// 8. Build active project sections
let generatedProjectSections = [];
for (const project of activeProjects) {
  let section = projectTemplate;
  section = section.replace(/__project_name__/g, project.job_name);
  section = section.replace(/__file_name__/g, project.file_name);
  section = section.replace(/__current_status_property__/g, project.status.toUpperCase());
  section = section.replace(/__priority__/g, project.priority || '\uD83D\uDFE2 ON THE RADAR');
  section = section.replace(/__project_id__/g, project.id);
  // Stamp project ID as HTML comment on its own line below the Priority line
  section = section.replace(
    /(\*\*Priority:\*\* .+)/m,
    `$1\n<!-- project-id: ${project.id} -->`
  );
  // Inject current_status directly — no LLM token
  const currentStatus = (project.current_status || '').trim();
  section = section.replace(/__status_prose__/g, currentStatus);

  // Conditionally strip the callout block if this project has no feed signals
  const hasSignals = projectsWithSignals === null || projectsWithSignals.has(project.id);
  if (!hasSignals) {
    section = section.replace(
      /\n> \[!info\] Proposed project file update[\s\S]*?(?=\n+\*\*Current Status)/,
      '\n'
    );
  }

  // Strip the entire Recent Activity block if there are no real signals
  // (i.e. the table still contains only the placeholder row)
  section = section.replace(
    /\n\*\*Recent Activity:\*\*\n\n\| Summary \| Time \|\n\|------\|-*------\|\n\| __recent_updates__ \| __time__ \|\n?/,
    '\n'
  );

  generatedProjectSections.push(section);
}

// 9. Build housekeeping section
let housekeepingSection = '';
if (housekeepingProjects.length > 0) {
  const hkList = housekeepingProjects
    .map(p => `- [[${p.file_name}|${p.job_name}]] _(${p.status})_`)
    .join('\n');
  housekeepingSection = `\n\n---\n\n## \uD83D\uDD35 Housekeeping\n\n${hkList}`;
}

// 10. Fill __day__ and strip Generated __time__ line
let filledTop = topPart
  .replace(/__day__/g, dayFormatted)
  .replace(/^Generated __time__\s*\n?/m, '');

// 11. Final Stitching
const finalSkeletonFile = filledTop.replace(/\|__day_date__\|__event__\|__context__\|/, calendarRows)
  + generatedProjectSections.join('\n\n---\n\n')
  + bottomPart
  + housekeepingSection;

return [
  {
    json: {
      skeleton_file: finalSkeletonFile,
      project_count: activeProjects.length,
      housekeeping_count: housekeepingProjects.length
    }
  }
];
